"""Reuse verified rendering, then present three context pairs on one page."""
import json
from pathlib import Path
import rock_prompt_set as s
import render_rock_prompt_diagnostic as renderer

OUT=s.OUT

def page(collection):
    cards=[]
    for i,entry in enumerate(collection['prompts'],1):
        key=entry['id'];p=json.loads((OUT/key/'protocol.json').read_text());boundary=8*60/p['bpm']
        players=''
        order=['unprompted','prompted'] if i%2 else ['prompted','unprompted']
        for condition in order:
            caption='With reference prompt' if condition=='prompted' else 'Without reference prompt'
            origin='dataset reference notes' if condition=='prompted' else 'AI-generated warmup'
            players+=f'<article data-boundary="{boundary}" data-condition="{condition}"><h3>{caption}</h3><p>First {boundary:.2f}s: {origin}. Then four bars of new AI notes.</p><audio controls preload="metadata" src="{key}/step128_{condition}.mp3"></audio><button class="jump">Play AI continuation from {boundary:.2f}s</button><p class="position"></p><a download href="{key}/step128_{condition}.mp3">Download MP3</a></article>'
        roles=', '.join(p['prefix_roles']).replace('_',' ')
        cards.append(f'<section data-id="{key}"><h2>Prompt {i} · {p["bpm"]} BPM</h2><p>Reference parts: {roles}.</p>'+players+'''<label>Which continuation sounds better? <select><option value="">Choose</option><option value="prompted">With reference prompt</option><option value="unprompted">Without reference prompt</option><option>Same</option><option>Neither</option></select></label>'''+f'<details><summary>Hear the original dataset excerpt</summary><p>Entirely reference MIDI, not generated by our model.</p><audio controls preload="none" src="{key}/dataset_reference.mp3"></audio></details></section>')
    script='''const key='rock-prompt-set-v1';let saved=JSON.parse(localStorage.getItem(key)||'{}');for(const s of document.querySelectorAll('section[data-id]')){const q=s.querySelector('select');q.value=saved[s.dataset.id]||'';q.onchange=()=>{saved[s.dataset.id]=q.value;localStorage.setItem(key,JSON.stringify(saved))};for(const card of s.querySelectorAll('article')){const a=card.querySelector('audio'),boundary=Number(card.dataset.boundary);card.querySelector('.jump').onclick=()=>{a.currentTime=boundary;a.play().catch(()=>document.getElementById('status').textContent='Press the audio play button to listen.')};a.ontimeupdate=()=>card.querySelector('.position').textContent=a.currentTime>=boundary?'AI continuation':(card.dataset.condition==='prompted'?'Dataset reference prompt':'AI warmup')}}for(const a of document.querySelectorAll('audio'))a.onplay=()=>{for(const b of document.querySelectorAll('audio'))if(a!==b)b.pause()};document.getElementById('save').onclick=()=>{const rows=[...document.querySelectorAll('section[data-id]')].map(s=>({prompt:s.dataset.id,choice:s.querySelector('select').value}));if(rows.some(r=>!r.choice)){document.getElementById('status').textContent='Please choose an answer for all three prompts.';return}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({schema:key,checkpoint_step:128,rows},null,2)],{type:'application/json'}));a.download='rock-prompt-set-v1.json';a.click()};'''
    (OUT/'player_check.js').write_text(script)
    (OUT/'listen.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Three new rock prompts</title><style>body{font:18px/1.6 system-ui;max-width:900px;margin:30px auto;padding:20px;background:#14212b;color:#edf5ef}section{background:#233746;padding:24px;border-radius:16px;margin:24px 0}article{border-top:1px solid #647581;padding:14px 0}audio{width:100%}button,select{font:inherit;padding:10px;margin:10px 0}a{color:#a6e7cb}.position{color:#b8e8cb}</style><h1>Does prompting help across different music?</h1><p>Three new compositions, each tested with and without its two-bar opening. All generated parts use the same final step-128 rock checkpoint. Within each pair, seed, tempo, instruments, sampling and loudness target are matched.</p><p>Use “Play AI continuation” to skip the opening. Prompted openings contain real dataset notes; no new reference note continues past the marked boundary, though release/reverb tails can remain briefly. Judge the new continuation, rather than the reference opening.</p>'''+''.join(cards)+'''<p><button id="save">Download choices</button></p><p id="status" role="status"></p><p>No new training was performed. These three prompts are a small diagnostic; a prompt preference does not establish autonomous composition quality or happy mood.</p><script>'''+script+'</script></html>',encoding='utf-8')

def main():
    collection=json.loads((OUT/'protocol.json').read_text());global_verified=json.loads((OUT/'remote_verification.json').read_text())
    assert global_verified['frozen_backbone_unchanged'] and global_verified['no_training']
    renderer.page=lambda p:None
    for entry in collection['prompts']:
        key=entry['id'];renderer.OUT=OUT/key;renderer.main()
    page(collection);print('THREE-PROMPT SET READY',flush=True)

if __name__=='__main__':main()
